There is a lot going on here, with many levels of nesting in the code - i would suggest breaking this down into more managable chunks. Here is how you could break down this function (_Without replacing hardcoded values_)
```python
def get_encoding(model):
    try:
        return tiktoken.encoding_for_model(model)
    except KeyError:
        print("Warning: model not found. Using cl100k_base encoding.")
        return tiktoken.get_encoding("cl100k_base")


def calculate_tokens_for_field(v, field, encoding):
    if field == "type" or field == "description":
        return 2 + len(encoding.encode(v[field]))
    elif field == "enum":
        return sum(3 + len(encoding.encode(o)) for o in v["enum"]) - 3
    else:
        print(f"Warning: not supported field {field}")
        return 0


def calculate_tokens_for_property(propertiesKey, propertiesValue, encoding):
    return len(encoding.encode(propertiesKey)) + sum(
        calculate_tokens_for_field(propertiesValue, field, encoding)
        for field in propertiesValue
    )


def calculate_tokens_for_function(function, encoding):
    tokens = len(encoding.encode(function["name"])) + len(encoding.encode(function["description"])) - 2
    if "parameters" in function and "properties" in function["parameters"]:
        properties = function["parameters"]["properties"]
        tokens += sum(calculate_tokens_for_property(k, v, encoding) for k, v in properties.items())
        tokens += 11 if len(properties) != 0 else 9
    return tokens


def num_tokens_from_functions(functions, model="gpt-3.5-turbo-0613"):
    """Return the number of tokens used by a list of functions."""
    encoding = get_encoding(model)
    return sum(calculate_tokens_for_function(function, encoding) for function in functions) + 12
```

